import {courseLibrary,libraryTabs} from './views-course.js';
import {esc,btn,title,empty,badge} from './ui.js';
import {allVideos} from './videos.js';

function related(v,catalog){return v.lessonIds.map(id=>catalog.lessons.find(l=>l.id===id)).filter(Boolean);}
function card(v,{state,catalog}){
 const p=state.videoProgress?.[v.id],lessons=related(v,catalog);
 return `<article class="panel video-card"><div class="tag-row">${badge(v.personal?'Pribadi':'Kurasi','outline')}${badge(v.language,'outline')}${p?.watched?badge('Ditonton · self-report','green'):''}</div><h2><a href="#videos/${esc(v.id)}">${esc(v.title)}</a></h2><p class="muted">${esc(v.publisher)}</p><p>${esc(v.prompt)}</p><div class="video-related">${lessons.map(l=>`<a href="#learn/${l.id}">${esc(l.title)}</a>`).join('')}${!lessons.length&&v.lessonIds.length?'<span class="muted">Pelajaran terkait tidak tersedia.</span>':''}</div><div class="btn-row section-gap">${btn(p?.resumeSeconds?`Lanjut dari ${p.resumeSeconds} detik`:'Tonton & belajar',`#videos/${v.id}`,'secondary small')}</div></article>`;
}
export function lessonVideos(l,ctx){
 const resources=allVideos(ctx.state).filter(v=>v.lessonIds.includes(l.id));
 return `<section class="panel lesson-videos" aria-label="Video pelajaran"><div class="panel-heading"><h2>Belajar lewat video</h2><a href="#videos?lesson=${l.id}">Tambah link</a></div><p class="muted">Opsional. Pause, prediksi, lalu coba sendiri. Menonton tidak menambah mastery.</p>${resources.length?resources.map(v=>`<div class="video-resource"><div>${badge(v.personal?'Pribadi':'Kurasi','outline')}<h3><a href="#videos/${v.id}">${esc(v.title)}</a></h3><p>${esc(v.publisher)} · ${esc(v.language)}</p><p>${esc(v.prompt)}</p></div>${btn('Tonton',`#videos/${v.id}`,'secondary small')}</div>`).join(''):'<p>Belum ada video terkait. Materi dan latihan tetap tersedia.</p>'}</section>`;
}
export function learningGuide(l,state,catalog){
 const exercise=l.exerciseIds.find(id=>catalog.exercises.some(e=>e.id===id));
 return `<nav class="learning-steps" aria-label="Langkah belajar"><a href="#lesson-content" data-lesson-anchor="lesson-content"><span>01 · Learn</span><strong>Baca & prediksi</strong></a><a href="#lesson-checkpoint" data-lesson-anchor="lesson-checkpoint"><span>02 · Check ${state.checkpointVersions?.[l.id]===l.version&&state.checkpointScores[l.id]===1?'✓':''}</span><strong>Uji pemahaman</strong></a><a href="${exercise?`#practice/${exercise}`:`#module/${l.moduleId}`}"><span>03 · Practice</span><strong>Coba mandiri</strong></a><a href="#review"><span>04 · Review</span><strong>Ingat kembali</strong></a></nav>`;
}
export function videoView(route,ctx){
 const {state,catalog}=ctx,resources=allVideos(state),q=route.query||new URLSearchParams();
 if(!route.id&&q.get('view')!=='videos'&&!q.has('source')&&!q.has('lesson'))return courseLibrary(route,ctx);
 if(route.id){
  const v=resources.find(x=>x.id===route.id);if(!v)return empty('Video tidak ditemukan.','Link mungkin sudah dihapus.',btn('Video library','#videos'));
  const p=state.videoProgress?.[v.id]||{notes:'',resumeSeconds:0,watched:false},lessons=related(v,catalog);
  return `${title('Watch · Reflect · Practice',v.title,v.publisher)}<div class="video-watch-layout"><section><div id="video-player" class="video-player" data-video-id="${esc(v.id)}"><div class="video-placeholder"><span class="video-play-mark" aria-hidden="true">▶</span><h2>Siap belajar?</h2><p>Muat pemutar YouTube saat kamu siap. Tidak ada autoplay.</p><button class="btn" type="button" data-action="load-video" data-id="${esc(v.id)}">Muat video${p.resumeSeconds?` dari ${p.resumeSeconds} detik`:''}</button></div></div><div class="video-toolbar"><a class="btn secondary small" href="https://www.youtube.com/watch?v=${v.videoId}&amp;t=${p.resumeSeconds}s" target="_blank" rel="noopener noreferrer">Buka di YouTube ↗</a><button class="btn secondary small" type="button" data-action="unload-video" data-id="${esc(v.id)}">Tutup pemutar</button>${v.sourceUrl?`<a class="source-link" href="${esc(v.sourceUrl)}" target="_blank" rel="noopener noreferrer">Sumber penerbit ↗</a>`:''}</div><p class="video-disclosure">Pemutar memakai YouTube privacy-enhanced mode. Saat dimuat, browser menghubungi YouTube; iklan dan pembatasan penerbit tetap berlaku. Jika video tidak tersedia, diblokir, atau koneksi offline, gunakan link YouTube atau lanjutkan materi.</p><section class="panel"><div class="eyebrow">Pause & explain</div><h2>Apa yang kamu pahami?</h2><p>${esc(v.prompt)}</p><p class="muted">Tutup video sebelum mengerjakan latihan mandiri.</p><div class="video-related">${lessons.map(l=>`${btn('Baca: '+l.title,`#learn/${l.id}`,'secondary small')}${btn('Coba latihan',l.exerciseIds.length?`#practice/${l.exerciseIds[0]}`:`#module/${l.moduleId}`,'small')}`).join('')||'<p>Belum terkait pelajaran yang tersedia. Pilih latihan dari <a href="#practice">Practice lab</a>.</p>'}</div></section></section><aside><form class="panel" data-form="video-progress" data-id="${esc(v.id)}"><div class="eyebrow">Catatan pribadi</div><h2>Simpan pemahamanmu</h2><label class="field">Ringkasan & pertanyaan<textarea name="notes" rows="7" maxlength="10000" placeholder="Jelaskan idenya tanpa menyalin video…">${esc(p.notes)}</textarea></label><label class="field">Lanjut dari (detik)<input name="resumeSeconds" type="number" min="0" max="86400" step="1" required value="${p.resumeSeconds}"></label><p class="muted">Bookmark manual. Posisi pemutar tidak direkam otomatis. Muat ulang pemutar untuk memakai bookmark baru.</p><label class="choice"><input name="watched" type="checkbox" ${p.watched?'checked':''}><span>Sudah saya tonton (self-report)</span></label><p class="muted">Status ini tidak memengaruhi checkpoint, latihan, atau mastery.</p><button type="submit" class="btn">Simpan catatan & bookmark</button><div id="video-feedback" role="status" class="section-gap"></div></form>${v.personal?`<div class="panel section-gap"><h3>Link pribadi</h3><p>Hapus link beserta catatan dan bookmark-nya.</p><button type="button" class="btn secondary small" data-action="delete-video" data-id="${esc(v.id)}">Hapus video pribadi</button></div>`:''}<div class="section-gap">${btn('Kembali ke library','#videos?view=videos','secondary')}</div></aside></div>`;
 }
 const search=(q.get('search')||'').toLowerCase(),source=q.get('source')||'',lesson=q.get('lesson')||'';
 const filtered=resources.filter(v=>(!source||(source==='personal'?v.personal:!v.personal))&&(!lesson||v.lessonIds.includes(lesson))&&(v.title+' '+v.publisher).toLowerCase().includes(search));
 const options=selected=>`<option value="">Semua pelajaran</option>${catalog.lessons.map(l=>`<option value="${l.id}" ${selected===l.id?'selected':''}>${esc(l.title)}</option>`).join('')}`;
 return `${title('Watch · Think · Try','Video library','Video pilihan untuk memperjelas ide, lalu latihan untuk mengujinya.')}${libraryTabs('videos')}<div class="banner">${resources.filter(v=>!v.personal).length} video kurasi · ${(state.videos||[]).length} link pribadi. Kurasi awal belum mencakup semua pelajaran; bahasa video tercantum pada tiap kartu.</div><form class="filter-bar video-filters" data-search="videos"><input type="hidden" name="view" value="videos"><input type="search" name="search" aria-label="Cari video" placeholder="Cari judul atau penerbit…" value="${esc(q.get('search')||'')}"><select name="source" aria-label="Sumber video"><option value="">Semua sumber</option><option value="curated" ${source==='curated'?'selected':''}>Kurasi</option><option value="personal" ${source==='personal'?'selected':''}>Pribadi</option></select><select name="lesson" aria-label="Filter pelajaran">${options(lesson)}</select><button class="btn secondary" type="submit">Cari video</button></form><div class="video-library-layout"><section><div class="grid grid-2">${filtered.map(v=>card(v,ctx)).join('')}</div>${!filtered.length?empty('Belum ada video cocok.','Tambah link pribadi atau ubah filter.',btn('Reset filter','#videos?view=videos','secondary')):''}</section><aside><form class="panel video-add" data-form="add-video"><div class="eyebrow">Your learning shelf</div><h2>Tambah video pribadi</h2><label class="field">Judul<input name="title" maxlength="200" required placeholder="Apa yang ingin dipelajari?"></label><label class="field">Link YouTube<input name="url" type="url" required maxlength="2048" placeholder="https://www.youtube.com/watch?v=…"></label><label class="field">Penerbit / channel (opsional)<input name="publisher" maxlength="200" placeholder="Nama channel"></label><label class="field">Pelajaran terkait (opsional)<select name="lessonId">${options(lesson).replace('Semua pelajaran','Tanpa pelajaran')}</select></label><p class="muted">Link disimpan di perangkat ini dan ikut backup. Gunakan Export di Settings untuk menyimpan salinan.</p><button class="btn" type="submit">Simpan video</button><div id="video-feedback" role="status" class="section-gap"></div></form></aside></div>`;
}
